void process_postgresql_packet(struct packet* packet) {
    if (packet->direction == CLIENT_TO_SERVER) {
        if (packet->length < MIN_CLIENT_PACKET_SIZE) {
            return;
        }

        char* user = extract_user_from_packet(packet);
        char* database = extract_database_from_packet(packet);

        struct session* session = find_or_create_session(packet->connection_id);

        if (session->status == UNINITIALIZED) {
            session->status = AUTHENTICATION_STARTED;
            strncpy(session->user, user, MAX_USERNAME_LENGTH);
            strncpy(session->database, database, MAX_DATABASE_NAME_LENGTH);
        }

        if (contains_md5_authentication(packet)) {
            session->auth_type = MD5;
            strncpy(session->md5_hash, extract_md5_hash(packet), MAX_MD5_HASH_LENGTH);
        } else {
            session->auth_type = CLEARTEXT;
            strncpy(session->password, extract_password(packet), MAX_PASSWORD_LENGTH);
        }

        free(user);
        free(database);
    } else {
        if (packet->length < MIN_SERVER_PACKET_SIZE) {
            return;
        }

        struct session* session = get_current_session(packet->connection_id);

        if (session && session->status == AUTHENTICATION_STARTED) {
            if (is_authentication_success(packet)) {
                session->status = AUTHENTICATION_SUCCESSFUL;
            } else if (is_authentication_challenge(packet)) {
                session->status = AWAITING_CLIENT_RESPONSE;
                strncpy(session->challenge, extract_challenge(packet), MAX_CHALLENGE_LENGTH);
            } else if (is_authentication_failure(packet)) {
                session->status = AUTHENTICATION_FAILED;
            }
        }
    }
}

void process_postgresql_packet(struct packet *packet) {
    if (packet->direction == CLIENT_TO_SERVER) {
        if (packet->length < MIN_CLIENT_PACKET_SIZE) {
            return;
        }

        struct session *session = find_existing_session(packet);
        if (!session) {
            session = create_new_session(packet);
            session->status = CONNECTION_INIT;
        }

        if (is_startup_packet(packet)) {
            extract_user_and_database(packet, session);
        }

        if (is_password_message(packet)) {
            if (contains_md5_auth(packet)) {
                handle_md5_authentication(packet, session);
            } else {
                handle_clear_text_authentication(packet, session);
            }
        }
    } else if (packet->direction == SERVER_TO_CLIENT) {
        struct session *session = find_existing_session(packet);
        if (session && is_authentication_response(packet)) {
            update_session_status(packet, session);
        }
    }

    cleanup_packet_resources(packet);
}

void process_postgres_packet(struct packet *pkt) {
    struct session *session;
    guint32 length;
    guint8 *data;

    if (pkt->from_client) {
        data = pkt->data;
        length = tvb_get_ntohl(pkt->length_field);

        if (length < 5) {
            return;  // Malformed packet
        }

        switch (data[0]) {
            case 'P':  // Startup or SSL request
                if (length >= 16 && !strncmp((char*)(data + 1), "POSTGRES", 8)) {
                    guint16 user_len, db_len;
                    char *user = NULL, *database = NULL;

                    user_len = tvb_get_ntohs(data + 1 + 12);
                    if (user_len > 0 && length > (guint)(1 + 12 + 2 + user_len + 2)) {
                        user = tvb_get_string_enc(NULL, data + 1 + 12 + 2, user_len, ENC_ASCII);
                    }

                    db_len = tvb_get_ntohs(data + 1 + 12 + 2 + user_len + 2);
                    if (db_len > 0 && length > (guint)(1 + 12 + 2 + user_len + 2 + db_len + 1)) {
                        database = tvb_get_string_enc(NULL, data + 1 + 12 + 2 + user_len + 2, db_len, ENC_ASCII);
                    }

                    session = session_find_or_create(pkt);
                    session->user = user;
                    session->database = database;
                    session->state = AUTH_STARTED;

                    if (strncmp((char*)(data + 1 + 12 + 2 + user_len + 2 + db_len + 2), "MD5", 3) == 0) {
                        session->auth_type = AUTH_MD5;
                    } else {
                        session->auth_type = AUTH_CLEARTEXT;
                    }
                }
                break;

            case 'p':  // Password message
                if (length >= 12) {
                    session = session_find(pkt);
                    if (session) {
                        char *password = tvb_get_string_enc(NULL, data + 1, length - 1, ENC_ASCII);
                        session->password = password;

                        if (session->auth_type == AUTH_MD5) {
                            session->state = WAITING_AUTH_RESPONSE;
                        } else {
                            session->state = AUTH_SUCCESS;
                        }
                    }
                }
                break;
        }
    } else {
        if (pkt->data[0] == 'R') {  // Authentication response
            guint32 auth_type = tvb_get_ntohl(pkt->data + 1);
            session = session_find(pkt);

            if (session && auth_type == 0) {
                session->state = AUTH_SUCCESS;
            }
        }
    }
}

void process_postgres_packet(struct packet *packet) {
    if (packet->from_client) {
        if (packet->length < MIN_CLIENT_PACKET_SIZE) {
            return;  // Invalid or incomplete packet
        }

        char *user = extract_user_from_packet(packet);
        char *database = extract_database_from_packet(packet);

        session_t *session = find_or_create_session(packet->session_id);
        if (!session) {
            return;  // Failed to create or find session
        }

        session->user = user;
        session->database = database;
        session->connection_status = CONNECTION_AUTHENTICATING;

        if (is_md5_authentication(packet)) {
            session->auth_type = AUTH_MD5;
            process_md5_authentication(packet, session);
        } else {
            session->auth_type = AUTH_CLEARTEXT;
            process_clear_text_authentication(packet, session);
        }
    } else {
        if (packet->length < MIN_SERVER_PACKET_SIZE) {
            return;  // Invalid or incomplete packet
        }

        session_t *session = find_session(packet->session_id);
        if (!session) {
            return;  // No existing session found
        }

        if (is_authentication_response(packet)) {
            handle_authentication_response(packet, session);
            session->connection_status = CONNECTION_AUTHENTICATED;
        } else {
            session->connection_status = CONNECTION_ESTABLISHED;
        }
    }

    free_allocated_resources(packet);
}

void process_postgres_packet(struct packet *packet) {
    if (packet->direction == CLIENT_TO_SERVER) {
        guint32 len = tvb_get_ntohl(packet->tvb, 0);
        if (len < 5) {
            return;
        }

        guint8 msg_type = tvb_get_guint8(packet->tvb, 1);
        if (msg_type == 'U') {
            struct session *session = find_or_create_session(packet);
            if (!session) {
                return;
            }

            gchar *username = extract_string_from_packet(packet, 5);
            gchar *database = extract_string_from_packet(packet, 5);

            session->username = username;
            session->database = database;
            session->state = AUTH_START;

            if (tvb_get_guint8(packet->tvb, 1) == 'p') {
                session->auth_method = AUTH_MD5;
            } else {
                session->auth_method = AUTH_CLEARTEXT;
            }
        }
    } else {
        guint8 auth_status = tvb_get_guint8(packet->tvb, 0);
        struct session *session = find_session(packet);
        if (!session) {
            return;
        }

        if (auth_status == 0) {
            session->state = AUTH_SUCCESS;
        } else {
            session->state = AUTH_FAILURE;
        }
    }

    cleanup_packet_resources(packet);
}
